/** Panel styles injected as a <style> tag (an external plugin cannot import a CSS module). */
export declare const PANEL_CSS = "\n.dsh-fe-panel {\n  --fe-bg: var(--dsw-alias-bg-base, #fff);\n  --fe-border: var(--dsw-alias-border-l2, #0000001a);\n  --fe-title-bg: var(--dsw-alias-bg-header, #f5f5f5);\n  --fe-title-fg: var(--dsw-alias-fg-base, #333);\n  --fe-divider: var(--dsw-alias-border-l2, #0000001a);\n  --fe-btn-hover: var(--dsw-alias-bg-hover, #0000000d);\n  background: var(--fe-bg);\n  position: fixed;\n  z-index: 1000;\n  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.2);\n  border: 1px solid var(--fe-border);\n  border-radius: 8px;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  font-family: system-ui, -apple-system, sans-serif;\n  font-size: 13px;\n  color: var(--fe-title-fg);\n}\n.dsh-fe-panel[data-maximized='true'] { border-radius: 0; box-shadow: none; }\n.dsh-fe-title-bar {\n  display: flex;\n  align-items: center;\n  background: var(--fe-title-bg);\n  padding: 0 8px;\n  height: 32px;\n  min-height: 32px;\n  cursor: grab;\n  user-select: none;\n  touch-action: none;\n  border-bottom: 1px solid var(--fe-border);\n  flex-shrink: 0;\n}\n.dsh-fe-title-bar:active { cursor: grabbing; }\n.dsh-fe-title-text {\n  flex: 1;\n  font-weight: 600;\n  font-size: 13px;\n  padding-left: 4px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.dsh-fe-title-actions { display: flex; gap: 2px; margin-left: auto; }\n.dsh-fe-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 24px;\n  height: 24px;\n  border: none;\n  background: transparent;\n  border-radius: 4px;\n  cursor: pointer;\n  font-size: 14px;\n  line-height: 1;\n  color: var(--fe-title-fg);\n  padding: 0;\n}\n.dsh-fe-btn:hover { background: var(--fe-btn-hover); }\n.dsh-fe-body { display: flex; flex: 1; min-height: 0; overflow: hidden; }\n.dsh-fe-pane { overflow: auto; min-width: 0; }\n.dsh-fe-pane--tree { flex-shrink: 0; border-right: none; }\n.dsh-fe-pane--preview { flex: 1; }\n.dsh-fe-divider {\n  width: 4px;\n  cursor: col-resize;\n  background: var(--fe-divider);\n  flex-shrink: 0;\n  transition: background 0.15s;\n}\n.dsh-fe-divider:hover, .dsh-fe-divider:active { background: var(--dsw-alias-accent, #4a90d9); }\n.dsh-fe-tree-empty, .dsh-fe-placeholder {\n  padding: 16px;\n  color: var(--dsw-alias-label-tertiary, #777);\n}\n.dsh-fe-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 4px 8px;\n  border-radius: 6px;\n  cursor: pointer;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.dsh-fe-row:hover { background: var(--fe-btn-hover); }\n.dsh-fe-row--dir { font-weight: 500; }\n.dsh-fe-disclosure { width: 12px; flex-shrink: 0; color: #999; }\n.dsh-fe-file-icon { flex-shrink: 0; color: #999; }\n.dsh-fe-row-name { overflow: hidden; text-overflow: ellipsis; }\n.dsh-fe-toolbar { display: flex; align-items: center; gap: 6px; padding: 6px 8px; border-bottom: 1px solid var(--fe-border); }\n.dsh-fe-refresh { border: none; background: transparent; cursor: pointer; font-size: 14px; color: var(--fe-title-fg); }\n.dsh-fe-children { padding-left: 14px; }\n.dsh-fe-menu {\n  position: fixed;\n  z-index: 1001;\n  min-width: 160px;\n  padding: 4px;\n  border: 1px solid var(--fe-border);\n  border-radius: 8px;\n  background: var(--fe-bg);\n  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.2);\n}\n.dsh-fe-menu-item {\n  display: flex;\n  width: 100%;\n  padding: 8px 10px;\n  border: none;\n  background: transparent;\n  border-radius: 6px;\n  cursor: pointer;\n  text-align: left;\n  color: var(--fe-title-fg);\n  font-size: 13px;\n}\n.dsh-fe-menu-item:hover { background: var(--fe-btn-hover); }\n.dsh-fe-preview-content { padding: 12px; }\n.dsh-fe-code {\n  margin: 0;\n  white-space: pre;\n  tab-size: 2;\n  font: 13px/1.6 ui-monospace, SFMono-Regular, Consolas, monospace;\n  overflow: auto;\n}\n.dsh-fe-image { max-width: 100%; max-height: 100%; }\n";
